// Sniperモード自動最適化 2026-07-15 10:56 / 2923件データ
// Sniper: 23件 勝率73.9% 平均0.4%
// 【Sniper条件（全6条件通過で採択）】
//   ① 当日出来高≥20日×1.2
//   ② ATR% < 3.0%
//   ③ 下ヒゲ優位（下ヒゲ長 ≥ 実体長）
//   ④ ストキャス≥75
//   ⑤ RSI 50〜70
//   ⑥ BB位置≥80%

function calculateScoreSniper(ind) {
  if (!ind) return null;
  const filters = [];
  let score = 0;

  // ① 当日出来高≥20日×1.2
  if (ind.volSurge >= 1.2) {
    score++;
    filters.push(`①vol急増(${ind.volSurge}x)`);
  }

  // ② ATR% < 3.0%
  if (ind.atrPct < 3.0) {
    score++;
    filters.push(`②ATR(${ind.atrPct}%)`);
  }

  // ③ 下ヒゲ優位（下ヒゲ長 ≥ 実体長）
  if (ind.lowerWick50) {
    score++;
    filters.push(`③下ヒゲ優位`);
  }

  // ④ ストキャス≥75
  if (ind.stochK >= 75) {
    score++;
    filters.push(`④STOCH(${ind.stochK.toFixed(0)})`);
  }

  // ⑤ RSI 50〜70
  if (!isNaN(ind.rsi14) && ind.rsi14 >= 50 && ind.rsi14 < 70) {
    score++;
    filters.push(`⑤RSI(${ind.rsi14.toFixed(0)})`);
  }

  // ⑥ BB位置≥80%
  if (ind.bbPct >= 0.80) {
    score++;
    filters.push(`⑥BB上部(${(ind.bbPct*100).toFixed(0)}%)`);
  }

  return { score, filters };
}
